void QThreadData::clearEvents()
{
    // Deleting an event may run arbitrary code (e.g. a destructor calling
    // deleteLater() or postEvent()), which locks postEventList.mutex and
    // modifies the list. So take the events out of the list while holding the
    // mutex, but delete them with the mutex unlocked; repeat until no new
    // events have been posted.
    QList<QPostEvent> events;
    forever {
        {
            const auto locker = qt_scoped_lock(postEventList.mutex);
            if (postEventList.isEmpty())
                break;
            events.swap(postEventList);
            postEventList.startOffset = 0;
            postEventList.insertionOffset = 0;
        }
        for (const auto &pe : std::as_const(events)) {
            if (pe.event) {
                pe.receiver->d_func()->postedEvents.fetchAndSubRelaxed(1);
                pe.event->m_posted = false;
                delete pe.event;
            }
        }
        events.clear();
    }
}

